-- ============================================================================
-- Migration 1063: Composites machines, India rates (USA twin cloned at India rates)
-- ============================================================================
-- Generated by scripts/generate-composites-india-machines-migration.js; re-run it and diff instead of editing.
--
-- Migration 796 seeded the 87 composites machines for the USA only, so a composite part priced in India had no machine on any step.
--
-- Source: memory/Countries data/India_XML_Data_.csv, commodity "Composites": each machine's direct and indirect overhead rate
-- (USD/hr, rounded to cents). Labour: the India rate of the process's wage grade (memory/Composites/wage_grade_associations), the value
-- every India row of that grade already carries (3 - Metal 1.73, 4 - Metal 2.30, 5 - Metal 2.75, 6 - Metal 3.52 USD/hr), written to
-- usd_labor_rate_per_hr AND usd_lhr_total (the column the machine selector reads; migration 1061 had to repair the twins that kept the
-- USA value there). The USA hand layup cells have no overhead rates in their file; their India rows do, and carry them.
-- 87 machines, each matched by machine class and exact name to its USA row:
--   Autoclave Cure            9 machine(s)
--   Automated Fiber Placement 9 machine(s)
--   Automated Tape Layup      13 machine(s)
--   Bench Operation           4 machine(s)
--   Hand Layup                8 machine(s)
--   Mold Preparation          4 machine(s)
--   Tool Clean                12 machine(s)
--   Ultrasonic Cut            28 machine(s)
--
-- Idempotent: an India row already present for a machine_class + machine_name is skipped.
-- Verify: SELECT machine_class, count(*) FROM mhr_records WHERE process_group = 'Composites' AND location = 'India' GROUP BY 1 ORDER BY 1;
--   -- expect 8 classes, 87 rows.
-- ============================================================================

DO $india_composites$
DECLARE
  cols text; sel text; r record; usa_id uuid; n integer := 0; missing text[] := '{}';
BEGIN
  SELECT
    string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
    string_agg(
      CASE c.column_name
        WHEN 'location'                                THEN '''India'''
        WHEN 'country_code'                            THEN '''IN'''
        WHEN 'direct_overhead_rate'                    THEN '$2'
        WHEN 'indirect_overhead_rate'                  THEN '$3'
        WHEN 'benchmark_direct_overhead_rate_usd_hr'   THEN '$2'
        WHEN 'benchmark_indirect_overhead_rate_usd_hr' THEN '$3'
        WHEN 'total_machine_hour_rate'                 THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'mhr_usd_per_hour'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'manual_mhr_value'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'fully_burdened_local_per_hr'             THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'usd_labor_rate_per_hr'                   THEN '$4'
        WHEN 'usd_lhr_total'                           THEN '$4'
        WHEN 'benchmark_labor_rate_usd_hr'             THEN '$4'
        WHEN 'benchmark_source_key'                    THEN 'usa_row.benchmark_source_key || '':India'''
        WHEN 'id'                                      THEN 'gen_random_uuid()'
        WHEN 'created_at'                              THEN 'now()'
        WHEN 'updated_at'                              THEN 'now()'
        ELSE 'usa_row.' || quote_ident(c.column_name)
      END, ', ' ORDER BY c.ordinal_position
    )
  INTO cols, sel
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'mhr_records' AND c.is_generated = 'NEVER';

  FOR r IN SELECT * FROM (VALUES
  ($str$autoclave_cure$str$, $str$American Autoclave 3m x 6.1m$str$, 2.75, 133.7, 3.01),
  ($str$autoclave_cure$str$, $str$ASC Process Systems EC 0.9m x 1.5m$str$, 2.75, 17.3, 1.21),
  ($str$autoclave_cure$str$, $str$ASC Process Systems EC 3m x 12.2m$str$, 2.75, 183.11, 3.9),
  ($str$autoclave_cure$str$, $str$ASC Process Systems EC 3m x 6.1m$str$, 2.75, 95.7, 3.01),
  ($str$autoclave_cure$str$, $str$Autoclave 0.9m x 1.5m$str$, 2.75, 17.12, 1.2),
  ($str$autoclave_cure$str$, $str$Autoclave 3m x 12.2m$str$, 2.75, 182.79, 3.91),
  ($str$autoclave_cure$str$, $str$Autoclave 3m x 6.1m$str$, 2.75, 111.91, 3.01),
  ($str$autoclave_cure$str$, $str$Autoclave 4m x 15m$str$, 2.75, 309.12, 4.46),
  ($str$autoclave_cure$str$, $str$Thermal Equipment Coroporation 3m x 6.1m$str$, 2.75, 107.83, 3.01),
  ($str$automated_fiber_placement$str$, $str$Automated Fiber Placement Machine - 11.4m x 4.2m x 4.2m$str$, 3.52, 214.35, 2.75),
  ($str$automated_fiber_placement$str$, $str$Automated Fiber Placement Machine - 18m x 8m x 8m$str$, 3.52, 337.63, 6.1),
  ($str$automated_fiber_placement$str$, $str$Automated Fiber Placement Machine - 2m x 1m x 1m$str$, 3.52, 29.87, 0.92),
  ($str$automated_fiber_placement$str$, $str$Coriolis C2 - 10m x 4.5m x 4.5m$str$, 3.52, 205.77, 2.45),
  ($str$automated_fiber_placement$str$, $str$Electroimpact AFP Machine - 10m x 3.6m x 3.6m$str$, 3.52, 141.77, 2.16),
  ($str$automated_fiber_placement$str$, $str$Fives Cincinnati Viper 4000 - 13.5m x 6m x 6m$str$, 3.52, 149.63, 3.72),
  ($str$automated_fiber_placement$str$, $str$Fives Cincinnati Viper 6000 - 18m x 8m x 8m$str$, 3.52, 337.63, 5.93),
  ($str$automated_fiber_placement$str$, $str$Mikrosam Discovery - 2m x 1m x 1m$str$, 3.52, 29.9, 0.93),
  ($str$automated_fiber_placement$str$, $str$MTorres TORRESFIBERLAYUP - 12.1m x 2.4m x 2.4m$str$, 3.52, 341.77, 1.91),
  ($str$automated_tape_layup$str$, $str$Automated Tape Layup Machine - 16m x 5.3m x 1.6m$str$, 3.52, 248.43, 3.78),
  ($str$automated_tape_layup$str$, $str$Automated Tape Layup Machine - 33m x 6.5m x 3m$str$, 3.52, 341.26, 8.41),
