  ($str$automated_tape_layup$str$, $str$Forest-Line ATLAS One - 20m x 4m x 1m$str$, 3.52, 276.4, 3.68),
  ($str$automated_tape_layup$str$, $str$Microsam Discovery - 2m x 1m x 1m$str$, 3.52, 30.31, 0.93),
  ($str$automated_tape_layup$str$, $str$Microsam Libra - 12m x 2.5m x 2.5m$str$, 3.52, 218.28, 1.92),
  ($str$automated_tape_layup$str$, $str$Microsam Taurus - 30m x 6m x 6m$str$, 3.52, 329.15, 7.73),
  ($str$automated_tape_layup$str$, $str$MTorres Layup 3D - 12.5m x 5.4m x 1.7m$str$, 3.52, 225.85, 3.24),
  ($str$automated_tape_layup$str$, $str$MTorres Layup 3D - 18m x 7.8m x 1.7m$str$, 3.52, 270.63, 5.81),
  ($str$composite_bench_operation$str$, $str$Manual Bench Cell - 16m x 4m$str$, 1.73, 0, 2.73),
