  ($str$composite_ultrasonic_cut$str$, $str$Bullmer Premiumcut ELC single ply cutter - 3.2m x 2.8m$str$, 2.3, 7.72, 2.61),
  ($str$composite_ultrasonic_cut$str$, $str$Bullmer Turbocut D2501 CV - 1.8m x 1.8m$str$, 2.3, 12.31, 1.76),
  ($str$composite_ultrasonic_cut$str$, $str$Bullmer Turbocut D2501 CV - 2.5m x 1.8m$str$, 2.3, 13.28, 1.94),
  ($str$composite_ultrasonic_cut$str$, $str$Gerber DCS1500 - 1.5m x 1.8m$str$, 2.3, 4.11, 1.2),
