  ($str$composite_ultrasonic_cut$str$, $str$Gerber Z1 1.8 long - 3m x 1.8m$str$, 2.3, 9.77, 1.6),
  ($str$composite_ultrasonic_cut$str$, $str$Gerber Z1 1.8 standard - 1.8m x 1.8m$str$, 2.3, 9.29, 1.6),
