  ($str$composite_ultrasonic_cut$str$, $str$Ultrasonic Cutter - 2.5m x 1.8m$str$, 2.3, 8.13, 1.69),
  ($str$composite_ultrasonic_cut$str$, $str$Ultrasonic Cutter - 3.1m x 2.1m$str$, 2.3, 12.41, 1.96),
  ($str$composite_ultrasonic_cut$str$, $str$Ultrasonic Cutter - 6.5m x 1.8m$str$, 2.3, 16.74, 1.88),
  ($str$composite_ultrasonic_cut$str$, $str$Zund G3 L 3200 standard - 3.2m x 1.8m$str$, 2.3, 10.11, 1.62),
  ($str$composite_ultrasonic_cut$str$, $str$Zund G3 L2500 standard - 2.5m x 1.8m$str$, 2.3, 8.65, 1.49),
  ($str$composite_ultrasonic_cut$str$, $str$Zund G3 L2500 variant - 2.5m x 1.8m$str$, 2.3, 9.63, 2.11),
  ($str$composite_ultrasonic_cut$str$, $str$Zund G3 L3200 variant - 3.2m x 1.8m$str$, 2.3, 11.08, 2.37),
  ($str$hand_layup$str$, $str$Clean Room Area - 16m x 4m$str$, 2.75, 140.06, 8.31),
  ($str$hand_layup$str$, $str$Clean Room Area - 2m x 2m$str$, 2.75, 8.75, 1.33),
