  ($str$mold_preparation$str$, $str$Mold Preparation Area 16m x 4m$str$, 1.73, 0, 2.73),
  ($str$mold_preparation$str$, $str$Mold Preparation Area 2m x 2m$str$, 1.73, 0, 0.98),
  ($str$mold_preparation$str$, $str$Mold Preparation Area 4m x 4m$str$, 1.73, 0, 1.33),
  ($str$mold_preparation$str$, $str$Mold Preparation Area 8m x 4m$str$, 1.73, 0, 1.79),
  ($str$tool_clean$str$, $str$Tool Clean Area: Adapt 1000W Laser - 16m x 4m$str$, 1.73, 47.71, 2.73),
  ($str$tool_clean$str$, $str$Tool Clean Area: Adapt 300W Laser - 2m x 2m$str$, 1.73, 13.63, 0.98),
  ($str$tool_clean$str$, $str$Tool Clean Area: Adapt 500W Laser - 4m x 4m$str$, 1.73, 17.13, 1.33),
  ($str$tool_clean$str$, $str$Tool Clean Area: Adapt 600W Laser - 8m x 4m$str$, 1.73, 19.58, 1.79),
  ($str$tool_clean$str$, $str$Tool Clean Area: Cold Jet Cryogenic - 16m x 4m$str$, 1.73, 3.53, 2.73),
  ($str$tool_clean$str$, $str$Tool Clean Area: Cold Jet Cryogenic - 2m x 2m$str$, 1.73, 1.62, 0.98),
  ($str$tool_clean$str$, $str$Tool Clean Area: Cold Jet Cryogenic - 4m x 4m$str$, 1.73, 1.23, 1.33),
  ($str$tool_clean$str$, $str$Tool Clean Area: Cold Jet Cryogenic - 8m x 4m$str$, 1.73, 1.35, 1.79),
  ($str$tool_clean$str$, $str$Tool Clean Area: Manual - 16m x 4m$str$, 1.73, 0, 2.73),
  ($str$tool_clean$str$, $str$Tool Clean Area: Manual - 2m x 2m$str$, 1.73, 0, 0.98),
  ($str$tool_clean$str$, $str$Tool Clean Area: Manual - 4m x 4m$str$, 1.73, 0, 1.33),
  ($str$tool_clean$str$, $str$Tool Clean Area: Manual - 8m x 4m$str$, 1.73, 0, 1.79)
  ) AS v(machine_class, usa_name, labor, direct, indirect)
  LOOP
    SELECT id INTO usa_id FROM mhr_records
    WHERE process_group = 'Composites' AND location = 'USA' AND machine_class = r.machine_class AND machine_name = r.usa_name
    LIMIT 1;
    IF usa_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.usa_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = 'India' AND m.machine_class = r.machine_class AND m.machine_name = r.usa_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format(
      'INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records usa_row WHERE usa_row.id = $1',
      cols, sel
    ) USING usa_id, r.direct, r.indirect, r.labor;
    n := n + 1;
  END LOOP;

  RAISE NOTICE 'Composites India rows inserted: %', n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE 'Composites India rows with no USA row (not inserted): %', missing;
  END IF;
END $india_composites$;

NOTIFY pgrst, 'reload schema';
